def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"

    digits = []
    while n != 0:
        remainder = n % 3
        digits.append(str(remainder))
        n //= 3

    # Reverse the list of digits to get the correct order
    digits.reverse()

    # Replace '-' with '+' for negative numbers
    return ''.join(['+' if d == '0' else '-' for d in digits])

