    dot_product = 0.0

    # Iterate over the keys of both dictionaries
    for key in set(v1.keys()) | set(v2.keys()):
        # Add the product of the corresponding values if they exist in both dictionaries
        dot_product += v1.get(key, 0) * v2.get(key, 0)

