def boustrophedon_order(matrix: list[list[int]]) -> list[int]:
    if not matrix:
        return []

    result = []
    rows = len(matrix)
    cols = len(matrix[0])
    i, j = 0, cols - 1

    while i < rows and j >= 0:
        # Add elements from the top row
        for k in range(cols):
            result.append(matrix[i][k])
            i += 1

        # Add elements from the rightmost column
        for k in range(i, rows):
            result.append(matrix[k][j])
            j -= 1

        # Check if there are more rows or columns to process
        if i < rows:
            # Add elements from the bottom row
            for k in range(j, -1, -1):
                result.append(matrix[i][k])
                i += 1

        if j >= 0:
            # Add elements from the leftmost column
            for k in range(i, rows):
                result.append(matrix[k][j])
                j -= 1

    return result
