def count_subsequence_matches(text: str, sub: str) -> int:
    if len(sub) > len(text):
        return 0

    dp = [0] * (len(text) + 1)
    dp[0] = 1

    for i in range(1, len(text) + 1):
        for j in range(len(sub), 0, -1):
            if text[i - 1] == sub[j - 1]:
                dp[i] += dp[i - 1]

    return dp[-1]
