import hashlib

def derive_key(passphrase: str, salt: bytes) -> bytes:
    # Ensure the passphrase is non-empty
    if not passphrase:
        raise ValueError("Passphrase must be non-empty")

    # Ensure the salt is at least 8 bytes long
    if len(salt) < 8:
        raise ValueError("Salt must be at least 8 bytes long")

    # Use SHA-256 hashing to derive the key
    return hashlib.sha256((passphrase + salt).encode()).digest()[:32]

