def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0

    # Calculate the number of bits needed for the largest number in the range
    max_num = hi
    num_bits = 0
    while max_num > 0:
        max_num >>= 1
        num_bits += 1

    # Initialize a list to store the count of set bits for each bit position
    set_bit_counts = [0] * num_bits

    # Iterate through each number in the range
    for i in range(lo, hi + 1):
        # Count the set bits for each bit position
        for j in range(num_bits):
            if i & (1 << j):
                set_bit_counts[j] += 1

    # Sum up the counts of set bits for all bit positions
    return sum(set_bit_counts)
