def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"

    digits = []
    while n != 0:
        remainder = n % 3
        digits.append(str(remainder))
        n //= 3

    # Reverse the list of digits to get the correct order
    digits.reverse()

    # Replace 2 with -1
    for i in range(len(digits)):
        if digits[i] == '2':
            digits[i] = '-'

    # Remove leading zeros
    while digits and digits[0] == '0':
        digits.pop(0)

    # Join the digits to form the final balanced ternary string
    return ''.join(digits)
