def boustrophedon_order(matrix: list[list[int]]) -> list[int]:
    if not matrix:
        return []

    result = []
    rows = len(matrix)
    cols = len(matrix[0])
    i, j = 0, 0

    while True:
        # Add current element to the result
        result.append(matrix[i][j])

        # Move to the next position based on the direction
        if i % 2 == 0:
            # Even row: move right
            j += 1
            if j >= cols:
                break
        else:
            # Odd row: move left
            j -= 1
            if j < 0:
                break

        # Move to the next row
        i += 1
        if i >= rows:
            break

    return result

def boustrophedon_order(matrix: list[list[int]]) -> list[int]:
    if not matrix:
        return []

    result = []
    rows = len(matrix)
    cols = len(matrix[0])
    i, j = 0, cols - 1

    while i < rows and j >= 0:
        for k in range(cols):
            result.append(matrix[i][k])
            i += 1

        for k in range(rows - 1, -1, -1):
            result.append(matrix[k][j])
            j -= 1

    return result

