def roman_char_distance(w1: str, w2: str) -> int:
    # Ensure both strings are of equal length or w1 is longer
    if len(w1) > len(w2):
        w1, w2 = w2, w1

    # Initialize the distance counter
    distance = 0

    # Compare characters position by position
    for i in range(len(w1)):
        if w1[i] != w2[i]:
            distance += 1

    # Add the difference in lengths to the distance
    distance += abs(len(w1) - len(w2))

    return distance

