def api_key_fingerprint(api_key: str) -> str:
    # Use SHA-256 hashing algorithm to generate the fingerprint
    hash_object = hashlib.sha256(api_key.encode())
    hex_dig = hash_object.hexdigest()

    # Ensure the fingerprint has at least 32 characters
    if len(hex_dig) < 32:
        hex_dig += '0' * (32 - len(hex_dig))

    return hex_dig.lower()

