        result = subprocess.run(['grep', '-E', pattern, path], capture_output=True, text=True)

        # Check if grep was successful
        if result.returncode == 0:
            # Split the output into lines and remove trailing newlines
            return [line.strip() for line in result.stdout.split('\n')]
        else:
            # Return an empty list if grep failed
            return []
    except FileNotFoundError:
        # Handle the case where the file does not exist
        print(f"Error: File '{path}' not found.")
        return []

