from typing import List

def count_queens(n: int, blocked: List[tuple[int, int]]) -> int:
    if n == 0:
        return 1

    def is_safe(board: List[List[bool]], row: int, col: int) -> bool:
        for i in range(row):
            if board[i][col]:
                return False

        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j]:
                return False

        for i, j in zip(range(row, -1, -1), range(col, n)):
            if board[i][j]:
                return False

        return True

    def backtrack(board: List[List[bool]], row: int) -> int:
        if row == n:
            return 1

        count = 0
        for col in range(n):
            if is_safe(board, row, col) and (row, col) not in blocked:
                board[row][col] = True
                count += backtrack(board, row + 1)
                board[row][col] = False

        return count

    board = [[False] * n for _ in range(n)]
    return backtrack(board, 0)
