    rows = len(grid)
    cols = len(grid[0])

    # Find starting point 'S' and ending point 'E'
    start = None
    end = None

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Initialize queue for BFS
    queue = deque([(start, 0)])
    visited = set()

    while queue:
        current, steps = queue.popleft()

        if current == end:
            return steps

        for dx, dy in directions:
            nx, ny = current[0] + dx, current[1] + dy

            # Check if new position is within bounds and not visited
            if 0 <= nx < rows and 0 <= ny < cols and (nx, ny) not in visited:
                visited.add((nx, ny))

                # If the new position is a wall, we can enter it
                if grid[nx][ny] == '#':
                    queue.append(((nx, ny), steps + 1))
                else:
                    queue.append(((nx, ny), steps))

    return -1
