import operator

def evaluate_expression(expression: str) -> float:
    if not expression:
        raise ValueError("Expression cannot be empty")

    # Define the mapping of operators to their corresponding functions
    ops = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv,
        '**': operator.pow,
        '-': operator.neg
    }

    def parse_expr(tokens):
        stack = []
        for token in tokens:
            if token.isdigit():
                stack.append(float(token))
            elif token in ops:
                right = stack.pop()
                left = stack.pop()
                result = ops[token](left, right)
                stack.append(result)
            elif token == '(':
                stack.append(parse_expr(tokens))
            elif token == ')':
                return stack.pop()
            else:
                raise ValueError(f"Unknown token: {token}")
        return stack[0]

    # Tokenize the input expression
    tokens = expression.replace(' ', '').split()

    try:
        return parse_expr(tokens)
    except ZeroDivisionError:
        raise ValueError("Division by zero")
