import operator

def evaluate_expression(expression: str) -> float:
    # Remove leading/trailing whitespace and split into tokens
    tokens = expression.strip().split()

    # Define operator precedence
    precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '/': 2,
        '**': 3
    }

    # Helper function to apply an operator to two operands
    def apply_operator(operators, values):
        while operators and operators[-1] != '(' and precedence[operators[-1]] >= precedence[token]:
            right = values.pop()
            left = values.pop()
            op = operators.pop()
            if op == '+':
                values.append(left + right)
            elif op == '-':
                values.append(left - right)
            elif op == '*':
                values.append(left * right)
            elif op == '/':
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                values.append(left / right)
            elif op == '**':
                values.append(left ** right)
        return values

    # Stack for operators and values
    operators = []
    values = []

    for token in tokens:
        if token.isdigit():
            values.append(float(token))
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()  # Remove '('
        else:
            while operators and operators[-1] != '(' and precedence[operators[-1]] > precedence[token]:
                apply_operator(operators, values)
            operators.append(token)

    # Apply remaining operators
    while operators:
        apply_operator(operators, values)

    # The result should be the only element left in the values stack
    if len(values) != 1:
        raise ValueError("invalid expression")
    return values[0]
