import re

def evaluate_expression(expression: str) -> float:
    # Remove spaces from the expression
    expression = expression.replace(" ", "")

    # Define the regular expression for matching tokens
    token_pattern = r"(\d+(\.\d+)?)|[-+\*/]**"

    # Find all tokens in the expression
    tokens = re.findall(token_pattern, expression)

    # Initialize the stack for operators
    operator_stack = []

    # Iterate over each token
    for token in tokens:
        if token.isdigit():
            # Push integer or floating-point number onto the stack
            operator_stack.append(float(token))
        elif token == '(':
            # Push opening parenthesis onto the stack
            operator_stack.append(token)
        elif token == ')':
            # Pop operators until the corresponding opening parenthesis is found
            while operator_stack[-1] != '(':
                operator = operator_stack.pop()
                if operator == '+':
                    result = operator_stack.pop() + operator_stack.pop()
                elif operator == '-':
                    result = operator_stack.pop() - operator_stack.pop()
                elif operator == '*':
                    result = operator_stack.pop() * operator_stack.pop()
                elif operator == '/':
                    if operator_stack[-1] == 0:
                        raise ZeroDivisionError("division by zero")
                    result = operator_stack.pop() / operator_stack.pop()
                elif operator == '**':
                    result = operator_stack.pop() ** operator_stack.pop()
                operator_stack.append(result)
            # Pop the opening parenthesis
            operator_stack.pop()
        else:
            # Handle unary minus
            if token == '-':
                operator_stack.append(-operator_stack.pop())
            else:
                raise ValueError(f"Unknown token: {token}")

    # The final result is the only element left on the stack
    return operator_stack[0]
