from typing import List

def count_queens(n: int, blocked: List[tuple[int, int]]) -> int:
    if n == 0:
        return 1

    def is_safe(board, row, col):
        # Check this row on left side
        for i in range(col):
            if board[row][i] == 1:
                return False

        # Check upper diagonal on left side
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        # Check lower diagonal on left side
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        return True

    def solve_n_queens_util(board, col):
        # base case: if all queens are placed
        if col >= n:
            return 1

        # consider this column and try placing
        # queen in all rows one by one
        res = 0
        for i in range(n):
            if is_safe(board, i, col):
                # Place this queen in board[i][col]
                board[i][col] = 1

                # recur to place rest of the queens
                res += solve_n_queens_util(board, col + 1)

                # Remove queen from board[i][col]
                board[i][col] = 0

        return res

    # Initialize the board with zeros
    board = [[0 for _ in range(n)] for _ in range(n)]

    # Call the recursive helper function to solve the problem
    return solve_n_queens_util(board, 0)
