from typing import List

def count_queens(n: int, blocked: List[tuple[int, int]]) -> int:
    if n == 0:
        return 1

    def is_safe(row, col):
        for r, c in blocked:
            if r == row or c == col or abs(r - row) == abs(c - col):
                return False
        return True

    def backtrack(row):
        if row == n:
            return 1

        count = 0
        for col in range(n):
            if is_safe(row, col):
                blocked.append((row, col))
                count += backtrack(row + 1)
                blocked.pop()

        return count

    return backtrack(0)
