import operator

def evaluate_expression(expression: str) -> float:
    def apply_operator(op, a, b):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            if b == 0:
                raise ZeroDivisionError("Cannot divide by zero")
            return a / b
        elif op == '**':
            return a ** b
        else:
            raise ValueError(f"Unsupported operator: {op}")

    def parse_expression(tokens):
        stack = []
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token.isdigit():
                num = int(token)
                while i + 1 < len(tokens) and tokens[i + 1].isdigit():
                    num = num * 10 + int(tokens[i + 1])
                    i += 1
                stack.append(num)
            elif token == '(':
                stack.append(token)
            elif token == ')':
                while stack[-1] != '(':
                    op = stack.pop()
                    b = stack.pop()
                    a = stack.pop()
                    stack.append(apply_operator(op, a, b))
                stack.pop()  # Remove the '('
            elif token in "+-*/**":
                while stack and stack[-1] in "+-*/**" and precedence(stack[-1]) >= precedence(token):
                    op = stack.pop()
                    b = stack.pop()
                    a = stack.pop()
                    stack.append(apply_operator(op, a, b))
                stack.append(token)
            i += 1
        while stack:
            op = stack.pop()
            b = stack.pop()
            a = stack.pop()
            stack.append(apply_operator(op, a, b))
        return stack[0]

    def precedence(op):
        if op in "+-":
            return 1
        elif op in "*/":
            return 2
        elif op == "**":
            return 3
        elif op == "(":
            return 4
        else:
            return 0

    tokens = expression.replace(" ", "").split()
    try:
        result = parse_expression(tokens)
        return result
    except ZeroDivisionError as e:
