def lcm(a, b):
    return abs(a*b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    # Extract moduli and remainders from the list
    moduli = [m for _, m in congruences]
    remainders = [r % m for r, _ in congruences]

    # Calculate the product of all moduli
    total_modulus = lcm(*moduli)

    # Create a matrix for the extended Euclidean algorithm
    matrix = [[total_modulus // m, -remainders[i]] for i, m in enumerate(moduli)]

    # Perform the extended Euclidean algorithm
    x, y = 0, 1
    for i in range(len(matrix)):
        old_x, x = x, old_x - matrix[i][0] * x
        old_y, y = y, old_y - matrix[i][1] * y

    # Adjust the solution to ensure it's within the range [0, total_modulus-1]
    solution = (x % total_modulus + total_modulus) % total_modulus

    # Verify the solution by checking each congruence
    for r, m in congruences:
        if solution % m != r % m:
            return None

    return (solution, total_modulus)
