    moduli = [mod for _, mod in congruences]
    remainders = [rem for rem, _ in congruences]

    # Calculate the product of all moduli
    product_moduli = 1
    for mod in moduli:
        product_moduli *= mod

    # Calculate the sum of products of remainders taken two at a time
    sum_remainder_products = sum(remainders[i]*remainders[j] for i in range(len(moduli)) for j in range(i+1, len(moduli)))

    # Calculate the modular inverse of the sum of products of remainders taken two at a time modulo each modulus
    inverses = []
    for mod in moduli:
        inverse = pow(sum_remainder_products, -1, mod)
        inverses.append(inverse)

    # Calculate the solution using the Chinese Remainder Theorem
    solution = 0
    for i in range(len(moduli)):
        solution += remainders[i] * inverses[i] * product_moduli // mod

    # Normalize the solution to be within the range [0, product_moduli-1]
    solution %= product_moduli

    # Check if the solution satisfies all congruences
    for r, m in congruences:
        if solution % m != r % m:
            return None

