def count_queens(n: int, blocked: List[tuple[int, int]]) -> int:
    if n == 0:
        return 1

    def is_safe(board: List[List[bool]], row: int, col: int) -> bool:
        # Check this row on left side
        for i in range(col):
            if board[row][i]:
                return False

        # Check upper diagonal on left side
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j]:
                return False

        # Check lower diagonal on left side
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i][j]:
                return False

        return True

    def solve_n_queens_util(board: List[List[bool]], col: int) -> int:
        # base case: If all queens are placed
        if col >= n:
            return 1

        # Consider this column and try placing this queen in all rows one by one
        count = 0
        for i in range(n):
            if is_safe(board, i, col):
                # Place this queen in board[i][col]
                board[i][col] = True

                # recur to place rest of the queens
                count += solve_n_queens_util(board, col + 1)

                # Remove queen from board[i][col] (backtrack)
                board[i][col] = False

        return count

    # Initialize the chessboard
    board = [[False for _ in range(n)] for _ in range(n)]

    # Call the helper function to solve the problem
    return solve_n_queens_util(board, 0)
