def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    # Create adjacency list representation of the graph
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Initialize distances and visited array
    dist = [float('inf')] * n
    visited = [False] * n

    # Perform BFS to find the shortest path
    def bfs(start):
        queue = [(start, 0)]
        while queue:
            current, distance = queue.pop(0)
            if current == target:
                return distance
            visited[current] = True
            for neighbor in adj_list[current]:
                if not visited[neighbor]:
                    queue.append((neighbor, distance + 1))
        return float('inf')

    # Calculate the shortest path from source to all other nodes
    min_distance = bfs(source)

    # Check if there is a valid path from source to target
    if min_distance == float('inf'):
        return 0

    # Count the number of shortest paths
    count = 0
    for i in range(n):
        if i != source and i != target:
            count += bfs(i)

