from math import gcd

def lcm(a, b):
    return abs(a*b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    # Extract moduli and remainders from the list
    mods = [c[1] for c in congruences]
    remainders = [c[0] % c[1] for c in congruences]

    # Calculate the product of all moduli
    product_mods = 1
    for mod in mods:
        product_mods *= mod

    # Calculate the product of the remainders
    product_remainders = 1
    for rem in remainders:
        product_remainders *= rem

    # Calculate the modular inverse of the product of remainders modulo each modulus
    inverses = []
    for i, mod in enumerate(mods):
        inv = pow(product_remainders, -1, mod)
        inverses.append(inv)

    # Solve the system of linear congruences using the Chinese Remainder Theorem
    result = 0
    for i, (rem, inv) in enumerate(zip(remainders, inverses)):
        result += rem * inv * product_mods // mods[i]

    # Reduce the result modulo the product of all moduli
    result %= product_mods

    # Check if the result satisfies all the original congruences
    for r, m in congruences:
        if result % m != r % m:
            return None

    return (result, product_mods)
