def decode_runs(encoded: str) -> str:
    result = []
    i = 0
    while i < len(encoded):
        if encoded[i] == '\\':
            # Check for escape sequences like \t, \n, etc.
            if i + 1 < len(encoded) and encoded[i+1].isalnum():
                result.append(chr(int(encoded[i+1:])))
                i += 2
            else:
                result.append('\\')
                i += 1
        elif encoded[i] != '~' and encoded[i].isdigit():
            # Decode runs of characters
            n = int(encoded[i])
            result.extend([encoded[i]] * n)
            i += 1
        else:
            # Single character without encoding
            result.append(encoded[i])
            i += 1
    return ''.join(result)
