from math import gcd

def lcm(a, b):
    return abs(a*b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    # Extract moduli and remainders from the list
    moduli = [mod for _, mod in congruences]
    remainders = [rem for rem, _ in congruences]

    # Calculate the product of all moduli
    product_moduli = 1
    for modulus in moduli:
        product_moduli *= modulus

    # Calculate the sum of products of each remainder with its corresponding modulus
    sum_remainder_modulus_product = sum(remainder * modulus for remainder, modulus in zip(remainders, moduli))

    # Calculate the modular inverse of the sum of products modulo the product of all moduli
    modular_inverse = pow(sum_remainder_modulus_product, -1, product_moduli)

    # Calculate the solution for x
    x = sum_remainder_modulus_product * modular_inverse % product_moduli

    # Check if the solution satisfies all congruences
    for i, (remainder, modulus) in enumerate(congruences):
        if x % modulus != remainder:
            return None

    return (x, product_moduli)
