def pack_bins(sizes: List[int], capacity: int) -> List[List[int]]:
    if not sizes:
        return []

    sizes.sort(reverse=True)
    bins = []
    total_capacity = 0

    for size in sizes:
        if size > capacity:
            raise ValueError("Item size exceeds capacity")

        if total_capacity + size <= capacity:
            bins[-1].append(size)
            total_capacity += size
        else:
            bins.append([size])
            total_capacity = size

    return bins
