def lcm(a, b):
    return abs(a*b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    # Extract moduli and remainders
    mods = [mod for _, mod in congruences]
    remainders = [rem for rem, _ in congruences]

    # Calculate the product of all moduli
    product_mods = 1
    for mod in mods:
        product_mods *= mod

    # Calculate the product of all remainders
    product_remainders = 1
    for rem in remainders:
        product_remainders *= rem

    # Calculate the modular inverse of each remainder modulo its corresponding modulus
    inverses = []
    for rem, mod in zip(remainders, mods):
        inv = pow(rem, -1, mod)
        inverses.append(inv)

    # Solve the system of linear equations
    x = 0
    for i in range(len(mods)):
        x += remainders[i] * inverses[i] * product_mods // mods[i]

    # Normalize the solution to be within the range [0, product_mods-1]
    x %= product_mods

    # Check if the solution satisfies all congruences
    for i in range(len(congruences)):
        if x % mods[i] != remainders[i]:
            return None

    return (x, product_mods)
