from math import gcd

def lcm(a, b):
    return abs(a*b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    # Extract moduli and remainders from the list
    moduli = [m for _, m in congruences]
    remainders = [r for r, _ in congruences]

    # Calculate the product of all moduli
    total_modulus = 1
    for modulus in moduli:
        total_modulus *= modulus

    # Calculate the inverse of each modulus modulo the total modulus
    inverses = []
    for modulus in moduli:
        inverse = pow(modulus, -1, total_modulus)
        inverses.append(inverse)

    # Solve the system of linear equations using the Chinese Remainder Theorem
    result = 0
    for i, (remainder, modulus) in enumerate(congruences):
        result += remainder * inverses[i] * modulus

    # Normalize the result to be within the range [0, total_modulus-1]
    result %= total_modulus

    # Check if the result satisfies all congruences
    for r, m in congruences:
        if result % m != r:
            return None

    return (result, total_modulus)
