import re

def is_local_redirect(target: str, host: str) -> bool:
    # Check for site-relative paths
    if target.startswith('/') and (len(target) == 1 or target[1] != '/'):
        return True

    # Check for absolute URLs
    elif target.startswith(('http://', 'https://')):
        url_parts = re.match(r'https?://([^/]+)', target)
        if url_parts and url_parts.group(1).lower() == host.lower():
            return True

    # Check for invalid characters
    if any(char < 32 or char >= 127 for char in target):
        return False

    return False
