def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []

    bins = []
    for size in sorted(sizes, reverse=True):
        found_bin = False
        for bin_ in bins:
            if sum(bin_) + size <= capacity:
                bin_.append(size)
                found_bin = True
                break
        if not found_bin:
            bins.append([size])

    return bins
