from itertools import combinations

def subsets_with_sum(nums: list[int], k: int) -> list[list[int]]:
    # Sort the array to ensure subsets are in non-decreasing order
    nums.sort()

    # Generate all possible subsets using combinations
    subsets = []
    for r in range(len(nums) + 1):
        for combo in combinations(nums, r):
            if sum(combo) == k:
                subsets.append(sorted(list(combo)))

    # Remove duplicate subsets
    unique_subsets = []
    seen = set()
    for subset in subsets:
        if tuple(subset) not in seen:
            unique_subsets.append(subset)
            seen.add(tuple(subset))

    return unique_subsets
