from datetime import datetime, timedelta

def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    start_date = datetime.strptime(start, "%Y-%m-%d")

    # Adjust for negative n by moving backwards
    if n < 0:
        while n < 0:
            start_date -= timedelta(days=1)
            if start_date.strftime("%A") != "Saturday" and start_date.strftime("%A") != "Sunday":
                break

    # Adjust for positive n by moving forwards
    else:
        while n > 0:
            start_date += timedelta(days=1)
            if start_date.strftime("%A") != "Saturday" and start_date.strftime("%A") != "Sunday":
                break

    # Ensure the result is within the valid range
    if start_date.year < 1900 or start_date.year > 2100:
        return "Invalid date"

    # Check if the result is a holiday
    if start_date.strftime("%Y-%m-%d") in holidays:
        return add_business_days(start_date.strftime("%Y-%m-%d"), -1, holidays)  # Move back one day

    return start_date.strftime("%Y-%m-%d")

# Example usage
print(add_business_days("2024-03-01", 1, ["2024-03-05"]))  # Output: "2024-03-04"
print(add_business_days("2024-03-01", -1, ["2024-03-05"]))  # Output: "2024-03-03"
print(add_business_days("2024-03-01", 0, ["2024-03-05"]))  # Output: "2024-03-01"
print(add_business_days("2024-03-01", 5, ["2024-03-05", "2024-03-06"]))  # Output: "2024-03-07"
print(add_business_days("2024-03-01", -5, ["2024-03-05", "2024-03-06"]))  # Output: "2024-02-28"
