def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not 2 <= from_base <= 36 or not 2 <= to_base <= 36:
        raise ValueError("Base must be between 2 and 36.")

    def to_decimal(num_str):
        return sum(int(digit, from_base) * (from_base ** idx) for idx, digit in enumerate(reversed(num_str)))

    def from_decimal(decimal_num):
        if decimal_num == 0:
            return "0"

        digits = []
        while decimal_num > 0:
            digits.append(chr((decimal_num % to_base) + ord('0')))
            decimal_num //= to_base

