from typing import List, Tuple

def free_slots(busy: List[Tuple[int, int]], day_start: int, day_end: int, min_len: int) -> List[Tuple[int, int]]:
    if day_start >= day_end:
        return []

    # Sort busy times by start time
    busy.sort(key=lambda x: x[0])

    free_slots = []
    current_free_start = day_start

    for start, end in busy:
        if start >= current_free_start + min_len:
            free_slots.append((current_free_start, start))

        current_free_start = max(current_free_start, end)

    # Check if there's a free slot after the last busy time
    if current_free_start < day_end:
        free_slots.append((current_free_start, day_end))

    return free_slots

