def fetch_target_allowed(url: str, allowed_hosts: list[str]) -> bool:
    # Check URL scheme
    if not url.lower().startswith(('http://', 'https://')):
        return False

    # Remove user info from URL
    url = re.sub(r'@[^\s]*', '', url)

    # Convert host to lowercase and remove trailing dot if present
    host = url.split('/')[2].lower()
    if host.endswith('.'):
        host = host[:-1]

    # Check if host matches any allowed host
    for allowed_host in allowed_hosts:
        if host == allowed_host.lower():
            return True

    return False

