from typing import List

def min_slides(grid: List[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    # Find the starting position (S)
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
                break

    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols and grid[x][y] != '#'

    def dfs(x, y, steps):
        if grid[x][y] == 'E':
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                new_steps = dfs(nx, ny, steps + 1)
                if new_steps != -1:
                    return new_steps

        return -1

    return dfs(start[0], start[1], 0)
