def free_slots(busy: List[Tuple[int, int]], day_start: int, day_end: int, min_len: int) -> List[Tuple[int, int]]:
    if day_start >= day_end:
        return []

    free_intervals = []
    current_free_start = day_start
    current_free_end = day_start

    for start, end in sorted(busy):
        if start < current_free_end:
            # Extend the current free interval
            current_free_end = max(current_free_end, end)
        else:
            # Start a new free interval
            if current_free_end - current_free_start >= min_len:
                free_intervals.append((current_free_start, current_free_end))
            current_free_start = start
            current_free_end = end

    # Check the last free interval
    if current_free_end - current_free_start >= min_len:
        free_intervals.append((current_free_start, current_free_end))

    return free_intervals
