import math

def evaluate_formula(formula: str, x: float) -> float:
    if not all(c.isalnum() or c == 'x' or c in '+-*/**()' or c in ['sqrt', 'abs', 'sin', 'cos'] for c in formula):
        raise ValueError("Invalid formula")

    def eval_expr(expr):
        if expr.isdigit():
            return float(expr)
        elif expr.startswith('-'):
            return -eval_expr(expr[1:])
        elif expr.startswith('('):
            return eval_expr(expr[1:-1])
        else:
            func = expr.split('(')[0]
            arg = expr.split('(')[1].split(')')[0]
            if func == 'sqrt':
                return math.sqrt(eval_expr(arg))
            elif func == 'abs':
                return abs(eval_expr(arg))
            elif func == 'sin':
                return math.sin(math.radians(eval_expr(arg)))
            elif func == 'cos':
                return math.cos(math.radians(eval_expr(arg)))

    stack = []
    i = 0
    while i < len(formula):
        if formula[i] == '(':
            stack.append(i)
        elif formula[i] == ')':
            start = stack.pop()
            subexpr = formula[start:i+1]
            value = eval_expr(subexpr)
            formula = formula[:start] + str(value) + formula[i+1:]
        elif formula[i] in '+-*/**':
            while stack and stack[-1] != '(' and ((stack[-1] == '*' or stack[-1] == '/') and formula[i] in '+-') or (stack[-1] == '+' or stack[-1] == '-') and formula[i] in '*'):
                op = stack.pop()
                right = stack.pop()
                left = stack.pop()
                stack.append(str(eval(f"{left} {op} {right}")))
            stack.append(formula[i])
        elif formula[i] == 'x':
            stack.append(x)
        elif formula[i].isdigit():
            num = ''
            while i < len(formula) and formula[i].isdigit():
                num += formula[i]
                i += 1
            stack.append(float(num))

        i += 1

    while len(stack) > 1:
        op = stack.pop()
        right = stack.pop()
        left = stack.pop()
        stack.append(str(eval(f"{left} {op} {right}")))

    return float(stack[0])
