def parse_csv(text: str) -> list[list[str]]:
    if not text:
        return []

    # Split the text into lines
    lines = text.strip().split('\n')

    def parse_line(line):
        result = []
        i = 0
        while i < len(line):
            if line[i] == '"':
                # Find the end of the quoted field
                j = i + 1
                while j < len(line) and (line[j] != '"' or line[j-1] != '"'):
                    j += 1
                if j == len(line):
                    raise ValueError("Unmatched double quote")
                field = line[i+1:j]
                i = j + 1
                if field.startswith('"') and field.endswith('"'):
                    field = field[1:-1].replace('""', '"')
                result.append(field)
            else:
                # Find the next comma or newline
                j = i + 1
                while j < len(line) and (line[j] != ',' and line[j] != '\n'):
                    j += 1
                if j == len(line):
                    break
                field = line[i:j]
                result.append(field)
                i = j
        return result

    records = [parse_line(line) for line in lines]
    return records

