import math

def evaluate_formula(formula: str, x: float) -> float:
    def parse_expression(expr):
        if expr.isdigit():
            return float(expr)
        elif expr.startswith('-'):
            return -parse_expression(expr[1:])
        elif expr.startswith('('):
            expr = expr[1:-1]
            depth = 0
            start = 0
            for i, char in enumerate(expr):
                if char == '(':
                    depth += 1
                elif char == ')':
                    depth -= 1
                    if depth == 0:
                        sub_expr = expr[start:i+1]
                        return parse_expression(sub_expr)
                if depth == 0 and char in '+-*/**':
                    return char
                start = i + 1
        else:
            raise ValueError("Invalid expression")

    def apply_operator(op, a, b):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            if b == 0:
                raise ZeroDivisionError("Cannot divide by zero")
            return a / b
        elif op == '**':
            return math.pow(a, b)

    def evaluate_subexpression(expr):
        tokens = expr.split()
        stack = []
        for token in tokens:
            if token.isdigit() or token in '+-*/**':
                stack.append(parse_expression(token))
            elif token in 'sqrt abs sin cos':
                operator = token
                arg = stack.pop()
                if operator == 'sqrt':
