                elif operator == 'abs':
                    stack.append(abs(arg))
                elif operator == 'sin':
                    stack.append(math.sin(math.radians(arg)))
                elif operator == 'cos':
                    stack.append(math.cos(math.radians(arg)))
            else:
                raise ValueError("Invalid expression")
        return stack[0]

    return evaluate_subexpression(formula.replace('x', str(x)))
