from typing import List, Tuple

def league_table(results: List[Tuple[str, str, int, int]]) -> List[Tuple[str, int, int, int]]:
    # Initialize the league table with zeros
    league = {team: [0, 0, 0] for team in set(home + away for home, away, _, _ in results)}

    # Update the league table based on the results
    for home, away, home_goals, away_goals in results:
        if home_goals > away_goals:
            league[home][0] += 3
            league[away][2] += 1
        elif home_goals < away_goals:
            league[away][0] += 3
            league[home][2] += 1
        else:
            league[home][1] += 1
            league[away][1] += 1

    # Sort the league table
    sorted_league = sorted(league.items(), key=lambda x: (-x[1][0], -x[1][1], -x[1][2], x[0]))

    return sorted_league
