def cheapest_route(edges: List[Tuple[str, str, int]], start: str, goal: str) -> Tuple[int, List[str]] | None:
    def dijkstra(graph: dict, start: str) -> dict:
        distances = {node: float('inf') for node in graph}
        distances[start] = 0
        queue = [(0, start)]

        while queue:
            current_distance, current_node = heapq.heappop(queue)

            if current_distance > distances[current_node]:
                continue

            for neighbor, weight in graph[current_node].items():
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(queue, (distance, neighbor))

        return distances

    def find_path(distances: dict, start: str, goal: str) -> List[str]:
        path = []
        current_node = goal

        while current_node != start:
            path.append(current_node)
            current_node = distances[current_node]['previous']

        path.append(start)
        path.reverse()

        return path

    graph = {}

    for u, v, w in edges:
        if u not in graph:
            graph[u] = {}
        if v not in graph:
            graph[v] = {}
        graph[u][v] = w
        graph[v][u] = w

    distances = dijkstra(graph, start)

    if distances[goal] == float('inf'):
        return None

    path = find_path(distances, start, goal)

    return distances[goal], path
