def cheapest_route(edges: List[Tuple[str, str, int]], start: str, goal: str) -> Tuple[int, List[str]] | None:
    # Initialize the distance dictionary with infinity for all nodes except the start node
    distances = {node: float('inf') for node in set(u for u, _, _ in edges)}
    distances[start] = 0

    # Initialize the predecessor dictionary to keep track of the shortest path
    predecessors = {}

    # Priority queue to store nodes to visit, ordered by their distance from the start node
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        # If we've reached the goal, reconstruct the path
        if current_node == goal:
            path = []
            while current_node != start:
                path.append(current_node)
                current_node = predecessors[current_node]
            path.append(start)
            path.reverse()
            return (current_distance, path)

        # Explore neighbors
        for neighbor, weight in edges:
            if neighbor == current_node:
                continue
            new_distance = current_distance + weight

            # Update the distance and predecessor if a shorter path is found
            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                predecessors[neighbor] = current_node
                heapq.heappush(priority_queue, (new_distance, neighbor))

    # If no path was found, return None
    return None

