        if home not in team_scores:
            team_scores[home] = {'wins': 0, 'draws': 0, 'losses': 0, 'total_points': 0}
        if away not in team_scores:
            team_scores[away] = {'wins': 0, 'draws': 0, 'losses': 0, 'total_points': 0}

        if home_goals > away_goals:
            team_scores[home]['wins'] += 1
            team_scores[home]['total_points'] += 3
        elif home_goals < away_goals:
            team_scores[away]['wins'] += 1
            team_scores[away]['total_points'] += 3
        else:
            team_scores[home]['draws'] += 1
            team_scores[away]['draws'] += 1
            team_scores[home]['total_points'] += 1
            team_scores[away]['total_points'] += 1

        team_scores[home]['goals_scored'] += home_goals
        team_scores[away]['goals_conceded'] += away_goals

