    sorted_teams = sorted(team_scores.items(), key=lambda x: (-x[1]['total_points'], -x[1]['goal_difference'], -x[1]['goals_scored'], x[0]))

    # Format the output as required
    result = [(team, score['total_points'], score['goal_difference'], score['goals_scored']) for team, score in sorted_teams]

