import math

def evaluate_formula(formula: str, x: float) -> float:
    def parse_expression(expression):
        stack = []
        current_number = ''
        current_operator = None
        for char in expression:
            if char.isdigit() or char == '.':
                current_number += char
            elif char in '+-*/**':
                if current_operator is not None:
                    stack.append((current_operator, float(current_number)))
                current_operator = char
                current_number = ''
            elif char == '(':
                stack.append(char)
            elif char == ')':
                while stack[-1] != '(':
                    operator, value = stack.pop()
                    if operator == '**':
                        value = math.pow(value, stack.pop())
                    elif operator == '*':
                        value *= stack.pop()
                    elif operator == '/':
                        value /= stack.pop()
                    elif operator == '-':
                        value -= stack.pop()
                    stack.append(value)
                stack.pop()  # Remove the '('
            elif char in 'sqrt abs sin cos':
                stack.append((char, x))
            else:
                raise ValueError(f"Invalid character '{char}' in formula")
        if current_operator is not None:
            stack.append((current_operator, float(current_number)))
        while len(stack) > 1:
            operator, value1 = stack.pop()
            operator, value2 = stack.pop()
            if operator == '**':
                value1 = math.pow(value1, value2)
            elif operator == '*':
                value1 *= value2
            elif operator == '/':
                value1 /= value2
            elif operator == '-':
                value1 -= value2
            stack.append(value1)
        return stack[0]

    try:
        return parse_expression(formula)
    except ZeroDivisionError:
        raise ZeroDivisionError("Division by zero occurred")
    except ValueError as e:
        raise ValueError(e)

