import math

def evaluate_formula(formula: str, x: float) -> float:
    def parse_expression(tokens):
        stack = []
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token == '(':
                stack.append(token)
            elif token == ')':
                while stack[-1] != '(':
                    op = stack.pop()
                    right = stack.pop()
                    left = stack.pop()
                    if op == '+':
                        stack.append(left + right)
                    elif op == '-':
                        stack.append(left - right)
                    elif op == '*':
                        stack.append(left * right)
                    elif op == '/':
                        if right == 0:
                            raise ZeroDivisionError("division by zero")
                        stack.append(left / right)
                    elif op == '**':
                        stack.append(math.pow(left, right))
                stack.pop()  # Remove the '('
            elif token.isdigit():
                num = int(token)
                stack.append(num)
            elif token in ['+', '-', '*', '/', '**']:
                stack.append(token)
            elif token in ['sqrt', 'abs', 'sin', 'cos']:
                stack.append(token)
            i += 1
        return stack[0]

    def apply_operator(op, a, b):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            if b == 0:
                raise ZeroDivisionError("division by zero")
            return a / b
        elif op == '**':
            return math.pow(a, b)

    def evaluate_subexpression(subexpr):
        tokens = subexpr.split()
        return parse_expression(tokens)

    def evaluate_formula_recursive(formula):
        tokens = formula.replace(' ', '').split()
        if len(tokens) == 1:
            return evaluate_subexpression(tokens[0])
        else:
            operator = tokens[1]
            left = evaluate_formula_recursive(tokens[2])
            right = evaluate_formula_recursive(tokens[4])
            return apply_operator(operator, left, right)

    try:
        return evaluate_formula_recursive(formula)
