def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    result = [[0] * n for _ in range(n)]

    for i in range(n // 2):
        start, end = i, n - i - 1

        # Rotate the top row
        for j in range(start, end + 1):
            result[start][j] = matrix[end - j + start][start]

        # Rotate the right column
        for j in range(start, end + 1):
            result[j][end] = matrix[end][n - j + start]

        # Rotate the bottom row
        for j in range(start, end + 1):
            result[end][n - j + start] = matrix[start + j - start][end]

        # Rotate the left column
        for j in range(start, end + 1):
            result[n - j + start][start] = matrix[start][n - j + start]

    return result
