def tokenize_code(source: str) -> list[tuple[str, str]]:
    if not source.strip():
        return []

    tokens = []
    current_token = ""
    current_kind = None

    for char in source:
        if char.isalnum() or char == "_":
            current_token += char
            current_kind = "NAME"
        elif char.isdigit():
            current_token += char
            current_kind = "NUMBER"
        elif char in "+-*/<=>(":
            current_token += char
            current_kind = "OP"
        elif char == ".":
            if current_kind == "NUMBER" and current_token[-1].isdigit():
                current_token += char
            else:
                raise ValueError(f"Invalid use of '.' in {current_token}")
        elif char in "\t\n":
            if current_token:
                tokens.append((current_kind, current_token))
                current_token = ""
                current_kind = None
        else:
            raise ValueError(f"Unexpected character '{char}'")

    if current_token:
        tokens.append((current_kind, current_token))

    return tokens
