import re

def is_allowed_webhook(url: str) -> bool:
    # Check if the URL starts with https://
    if not url.lower().startswith('https://'):
        return False

    # Remove leading/trailing whitespace and special characters
    cleaned_url = re.sub(r'\s+|[^a-zA-Z0-9.-]', '', url)

    # Check if the cleaned URL contains any backslashes, spaces, or control characters
    if '\\' in cleaned_url or ' ' in cleaned_url or '\x00' <= ord(cleaned_url[-1]) < 32:
        return False

    # Split the URL into components
    parts = cleaned_url.split('@')

    # Check if there's a username/password part
    if len(parts) > 1:
        user_parts = parts[0].split(':')
        if len(user_parts) != 2:
            return False

    # Extract the host part
    host_part = parts[0]

    # Check if the host part ends with a dot
    if not host_part.endswith('.'):
        return False

    # Split the host part into labels
    labels = host_part[:-1].split('.')

    # Check if the host part has at least two labels
    if len(labels) < 2:
        return False

    # Check if the host part contains only valid characters
    for label in labels:
        if not re.match(r'^[a-zA-Z0-9-]+$', label):
            return False

    # Check if the last label is not empty
    if not labels[-1]:
        return False

    # Check if the host part does not end with .localhost
    if host_part.lower().endswith('.localhost'):
        return False

    # Check if the port is absent or 443
    if ':' in host_part:
        port = int(host_part.split(':')[1])
        if port != 443:
            return False

    return True

