import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    if not source.strip():
        return []

    tokens = []
    for match in re.finditer(r'\b\d+(\.\d+)?\b|\b[a-zA-Z_][a-zA-Z0-9_]*\b|[+\-*\/<>=(),]|==|!=|<=|>=', source):
        kind = 'NUMBER' if '.' in match.group() else 'NAME'
        tokens.append((kind, match.group()))

    # Check for invalid characters or misplaced operators
    for char in source:
        if char.isalnum() or char == '_':
            continue
        elif char in '+-*/<=>,':
            if len(tokens) < 2 or tokens[-1][0] != 'OP':
                raise ValueError(f"Invalid character '{char}' found")
            tokens.pop()
        else:
            raise ValueError(f"Invalid character '{char}' found")

    return tokens
