    for home, away, home_goals, away_goals in results:
        # Update the league data for both teams
        if home in league_data:
            league_data[home]['wins'] += 1
            league_data[home]['losses'] += 1
            league_data[home]['draws'] += 1
            league_data[home]['total_goals'] += home_goals + away_goals
            league_data[home]['total_conceded'] += away_goals + home_goals
        else:
            league_data[home] = {'wins': 1, 'losses': 0, 'draws': 0, 'total_goals': home_goals + away_goals, 'total_conceded': away_goals + home_goals}

        if away in league_data:
            league_data[away]['wins'] += 1
            league_data[away]['losses'] += 1
            league_data[away]['draws'] += 1
            league_data[away]['total_goals'] += away_goals + home_goals
            league_data[away]['total_conceded'] += home_goals + away_goals
        else:
            league_data[away] = {'wins': 1, 'losses': 0, 'draws': 0, 'total_goals': away_goals + home_goals, 'total_conceded': home_goals + away_goals}

    # Calculate points, goal difference, and goals scored for each team
