import re

def is_public_ip(ip_str: str) -> bool:
    # Regular expression pattern for validating IPv4 addresses
    ipv4_pattern = r'^(\d{1,3}\.){3}\d{1,3}$'

    # Regular expression pattern for validating IPv6 addresses
    ipv6_pattern = r'^([0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}(:[0-9a-fA-F]{1,4})?$'

    # Check if the input matches either IPv4 or IPv6 pattern
    if re.match(ipv4_pattern, ip_str):
        # Split the IPv4 address into its components
