import re

def evaluate_expression(expr: str) -> int:
    # Remove spaces and split into tokens
    tokens = re.findall(r'\d+|\+|-|\*|\/|^|\(|\)', expr.replace(' ', ''))

    # Define helper functions for each operator
    def add(a, b):
        return a + b

    def subtract(a, b):
        return a - b

    def multiply(a, b):
        return a * b

    def divide(a, b):
        if b == 0:
            raise ZeroDivisionError("Cannot divide by zero")
        return a // b

    def power(a, b):
        return a ** b

    # Map token strings to their corresponding functions
    ops = {
        '+': add,
        '-': subtract,
        '*': multiply,
        '/': divide,
        '^': power
    }

    # Evaluate the expression using a stack-based approach
    stack = []
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token.isdigit():
            stack.append(int(token))
        elif token in ops:
            op = ops[token]
            b = stack.pop()
            a = stack.pop()
            result = op(a, b)
            stack.append(result)
        elif token == '(':
            j = i + 1
            depth = 1
            while j < len(tokens) and depth > 0:
                if tokens[j] == '(':
                    depth += 1
                elif tokens[j] == ')':
                    depth -= 1
                j += 1
            sub_expr = ' '.join(tokens[i+1:j])
            stack.append(evaluate_expression(sub_expr))
            i = j - 1
        elif token == '-':
            if i == 0 or tokens[i-1] in ['(', '-', '*', '/', '^']:
                stack.append(-int(tokens[i]))
            else:
                stack.append(-stack.pop())
        i += 1

    return stack[0]
