import re

def is_allowed_webhook(url: str) -> bool:
    # Check if the URL starts with https://
    if not url.lower().startswith('https://'):
        return False

    # Remove the protocol prefix
    url = url[8:]

    # Check for backslashes, spaces, or control characters
    if re.search(r'[\\s\0-\x1f]', url):
        return False

    # Split the URL into user@host:port parts
    parts = url.split('@')
    if len(parts) != 2:
        return False

    username, host_port = parts

    # Check for localhost in the host part
    if 'localhost' in host_port.lower():
        return False

    # Check for .localhost in the host part
    if host_port.endswith('.localhost'):
        return False

    # Split the host part into labels
    labels = host_port.split('.')

    # Check if there are at least two labels
    if len(labels) < 2:
        return False

    # Check each label
    for label in labels:
        if not re.match(r'^[a-zA-Z0-9-]+$', label):
            return False

    # Check the last label
    if not re.match(r'^[a-zA-Z]+$', labels[-1]):
        return False

    # Check if the port is absent or 443
    if ':' in host_port:
        port = int(host_port.split(':')[1])
        if port != 443:
            return False

    return True

