    def eval_sub_expr(sub_expr):
        # Replace parentheses with their evaluated values
        while "(" in sub_expr:
            match = re.search(parenthesis_pattern, sub_expr)
            if match:
                sub_expr = sub_expr[:match.start()] + str(eval_sub_expr(match.group(1))) + sub_expr[match.end():]

