from typing import List, Tuple

def process_orders(events: List[Tuple[str, str, int]]) -> Tuple[dict[str, int], List[Tuple[str, int]]]:
    stock = {}
    waiting = []

    for kind, item, quantity in events:
        if kind == 'receive':
            stock[item] = max(0, stock.get(item, 0) + quantity)
        elif kind == 'order':
            if item in stock and stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting.append((item, quantity))

    # Fulfill pending orders based on arrival order
    for item, quantity in sorted(waiting):
        if item in stock and stock[item] >= quantity:
            stock[item] -= quantity

    return stock, waiting
