    failed = []

    for i, op in enumerate(ops):
        action, account, amount = op

        if account not in balances:
            failed.append(i)
            continue

        if action == 'deposit':
            if amount <= 0:
                failed.append(i)
                continue
            final_balances[account] += amount

        elif action == 'withdraw':
            if amount <= 0 or final_balances[account] < amount:
                failed.append(i)
                continue
            final_balances[account] -= amount

        elif action == 'transfer':
            if amount <= 0 or final_balances[account] < amount + 2:
                failed.append(i)
                continue
            final_balances[account] -= amount + 2
            final_balances[op[1]] += amount

        elif action == 'freeze':
            if final_balances[account] > 0:
                failed.append(i)
                continue
            final_balances[account] = 0

        elif action == 'unfreeze':
            if final_balances[account] < 0:
                failed.append(i)
                continue
            final_balances[account] = 0

    return final_balances, failed
